import { Field, FieldContent, FieldDescription, FieldLabel } from "@/registry/erbium/ui/field";
import { Switch } from "@/registry/erbium/ui/switch";

export function SwitchDescription() {
  return (
    <Field orientation="horizontal" className="max-w-sm">
      <FieldContent>
        <FieldLabel>Share across devices</FieldLabel>
        <FieldDescription>
          Focus is shared across devices, and turns off when you leave the app.
        </FieldDescription>
      </FieldContent>
      <Switch />
    </Field>
  );
}

import { SwitchDescription } from "../examples/upstream/switch-description";

const Example = () => <SwitchDescription />;

export default Example;
